SELECT COUNT(*) 
FROM invoice 
WHERE invoice_date BETWEEN '2022-01-01 00:00:00'::timestamp AND '2022-12-31 23:59:59'::timestamp;

SELECT SUM(total) 
FROM invoice 
WHERE invoice_date BETWEEN '2023-01-01 00:00:00'::timestamp AND '2023-12-31 23:59:59'::timestamp;

SELECT COUNT(track_id) AS num_tracks_not_purchased
FROM track
WHERE track_id NOT IN (
    SELECT track_id
    FROM invoice_line
);

SELECT COUNT(*) 
FROM customer 
WHERE company IS NULL;
